def hook(ctx, nb):
    p = ctx.get('predicates') or {}
    s = ctx.get('state') or {}
    stage = nb.get('stage') or 'start'
    if p.get('unknown_column_error') or p.get('syntax_error') or s.get('last_error_kind') in ('unknown_col', 'syntax'):
        stage = 'need_schema_probe'
        nb['fixing_unknown_column'] = bool(p.get('unknown_column_error'))
    elif p.get('last_result_empty') and not p.get('mutation_task'):
        stage = 'fixing_empty_result'
    elif p.get('repeated_sql') or (s.get('loop_streak') or 0) >= 2:
        stage = 'repeated_query_loop'
    elif p.get('text_only_loop') or (s.get('text_only_streak') or 0) >= 2:
        stage = 'text_numeric_handling'
    elif p.get('mutation_task') and p.get('mutation_not_attempted'):
        stage = 'mutation_needs_execution'
    elif p.get('mutation_task') and s.get('mutation_attempted'):
        stage = 'ready_to_commit_candidate'
    if p.get('candidate_answer_available') and not s.get('candidate_implausible'):
        nb['candidate_available'] = True
    if p.get('remaining_rounds_low'):
        nb['low_rounds'] = True
    nb['stage'] = stage
    return None

def hook(ctx, nb):
    stage = nb.get('stage')
    msg = ''
    if stage == 'need_schema_probe':
        msg = 'Schema recovery: use SHOW TABLES, then DESCRIBE the exact table name with MySQL backticks. Do not use double quotes for identifiers; quote every column name containing spaces, punctuation, or reserved words.'
    elif stage == 'fixing_empty_result':
        msg = 'Empty SELECT recovery: inspect a few sample rows and distinct values for the filtered columns. Stored values may be text, contain punctuation, newlines, or different casing, so relax one predicate or use LIKE before reapplying filters.'
    elif stage == 'text_numeric_handling':
        msg = 'Text numeric handling: when ranking, averaging, or comparing numbers stored as text, clean separators and CAST to SIGNED or DECIMAL. Avoid lexicographic ordering for numeric comparisons.'
    elif stage == 'mutation_needs_execution':
        msg = 'Mutation task: execute the INSERT, UPDATE, or DELETE before committing. An empty tool result can still mean the data-changing statement ran; verify the affected row or count with SELECT.'
    elif stage == 'ready_to_commit_candidate':
        msg = 'Mutation verification: after a data-changing statement, run a targeted SELECT to confirm the intended rows and literal formatting. If the database state matches the request, commit a concise final answer.'
    elif stage == 'repeated_query_loop':
        msg = 'Repeated query loop: change strategy instead of rerunning the same SQL. Probe schema, sample values, or predicates, then simplify filters or adjust quoting/casting.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

def hook(ctx, nb):
    a = ctx.get('action') or {}
    p = ctx.get('predicates') or {}
    if a.get('tool') != 'commit_final_answer':
        return None
    if p.get('commit_before_sql') or p.get('no_sql_yet'):
        return {'kind': 'block_and_prompt', 'message': 'Run at least one SQL query to inspect or modify the database before committing a final answer.'}
    if p.get('commit_empty_answer') and not (p.get('mutation_task') and (p.get('mutation_not_attempted') or nb.get('stage') == 'mutation_needs_execution')):
        return {'kind': 'block_and_prompt', 'message': 'Do not commit an empty answer for a SELECT-style task. Use SQL evidence to provide the requested values, or execute the mutation first for data-changing tasks.'}
    if p.get('mutation_task') and p.get('mutation_not_attempted') and not (p.get('remaining_rounds_low') and nb.get('stage') == 'mutation_needs_execution'):
        return {'kind': 'block_and_prompt', 'message': 'This is a database mutation task. Execute the INSERT, UPDATE, or DELETE before committing; the final text alone will not change the database state.'}
    return None
